#include "patched-collision_scheduler.hpp"
#include <iostream>
using namespace raikou::pic_collisions;
int count=0;void check(bool a,const char*s){++count;if(!a)throw Error(s);}template<class F>void budget_reject(F f){bool ok=false;try{f();}catch(const Error&e){ok=std::string(e.what())=="scheduler candidate input limit";}check(ok,"size rejection before other candidate validation");}
int main(){try{std::string H(64,'a'),K(64,'b');Packet p{"p","e",1,2,9.1093837139e-31,{1e7,0,0}},n{"n","H2O",1,8,2.9915e-26,{0,0,0}};Channel ch{"c","e","H2O",H,K,Observable::ExclusiveEvent,[](double){return 1e-20;}};auto rows=candidates({p},{n},{{1,1e-12}},{ch});Clock c{1,0,10,11,H,H,H,10.5,0};Scheduler s(91);auto before=s.checkpoint();budget_reject([&]{s.prepare(c,rows,0);});check(s.checkpoint()==before,"size refusal preserves RNG");check(!s.prepare(c,{},0).event(),"empty vector fits zero limit");auto more=rows[0];more.channel_id="second";std::vector<Candidate>two{rows[0],more};budget_reject([&]{s.prepare(c,two,1);});check(s.prepare(c,two,2).total_rate_s()==2*rows[0].rate_s,"exact size boundary admitted");auto poison=two;poison[0].rate_s=-1;budget_reject([&]{s.prepare(c,poison,1);});check(s.checkpoint()==before,"all prepare-only operations preserve RNG");auto a=s.prepare(c,rows),b=s.prepare(c,rows,1);check(a.event_subflow_elapsed_s()==b.event_subflow_elapsed_s(),"new default limit preserves deterministic clock");auto forced=rows;forced[0].sigma_m2*=1e6;forced[0].rate_s*=1e6;auto sub=c;sub.collision_elapsed_s=.6;auto first=s.prepare(sub,forced);check(first.event().has_value(),"forced event inside remaining subflow");check(first.event_subflow_elapsed_s()>.6&&first.event_subflow_elapsed_s()<1,"consumed elapsed retained in sampled subflow");check(first.frozen_physical_stage_s()==10.5,"sampled subflow is independent of global stage");check(s.try_publish(first),"subflow RNG publication");sub.collision_elapsed_s=first.event_subflow_elapsed_s();auto second=s.prepare(sub,forced);check(second.event()&&second.event_subflow_elapsed_s()>first.event_subflow_elapsed_s(),"successive subflow event respects consumed elapsed");check(second.frozen_physical_stage_s()==10.5,"successive event does not move physical stage");std::cout<<count<<" prepare-size and stage checks passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
